import { unstable_cache } from 'next/cache';
import fs from 'fs/promises';
import path from 'path';

// Define the Post type
export type Post = {
  id: string;
  title: string;
  content: string;
  createdAt: string;
};

const dataFilePath = path.join(process.cwd(), 'lib/data.json');

// Internal function to read data directly from file
async function readData(): Promise<Post[]> {
  try {
    const data = await fs.readFile(dataFilePath, 'utf-8');
    return JSON.parse(data);
  } catch (error) {
    // If file doesn't exist or is empty, return empty array
    return [];
  }
}

// Function to add a post
export async function addPost(post: Post) {
  const posts = await readData();
  posts.push(post);
  await fs.writeFile(dataFilePath, JSON.stringify(posts, null, 2));
}

// Cached function to get posts
// This function will cache the result based on the 'posts' tag
export const getPosts = unstable_cache(
  async () => {
    return readData();
  },
  ['posts-cache-key'], // Cache key
  { tags: ['posts'] } // Cache tags
);

